import{_ as n,a0 as a,w as s,s as u,ao as p,I as r,a1 as o,A as i,x as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const h=JSON.parse('{"title":"物聯網安全審計工具集錦 | LCTT x X-CMD","titleTemplate":false,"description":"物聯網安全審計工具集錦 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"物聯網安全審計工具集錦 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"物聯網安全審計工具集錦 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220502 Tools You Can Use for the Security Audit of IoT Devices","title":"物聯網安全審計工具集錦","tag":"202205","desc":""},"relativePath":"202205/20220502 Tools You Can Use for the Security Audit of IoT Devices.md","filePath":"[post].md"}'),d={name:"202205/20220502 Tools You Can Use for the Security Audit of IoT Devices.md"};function f(m,t,b,T,w,k){const e=a("Link");return s(),u("div",null,[t[29]||(t[29]=p('<h1 id="物聯網安全審計工具集錦" tabindex="-1">物聯網安全審計工具集錦 <a class="header-anchor" href="#物聯網安全審計工具集錦" aria-label="Permalink to “物聯網安全審計工具集錦”">​</a></h1><p>數字化轉型涉及數據驅動的決策與人工智能（AI）的結合。重要數據通過物聯網（IoT）設備和智能組件進行傳播。由於物聯網設備常常處於不安全的環境，而且由於缺乏內生安全機制的脆弱性，很難免於潛在的網絡攻擊。以下是一些用於實現安全審計的開源工具，可以降低此類攻擊風險。</p><p><img src="https://img.linux.net.cn/data/attachment/album/202205/09/090119h337d3shyoj3ou28.jpg" alt=""></p><p>網絡攻擊者和嗅探器可以從物聯網設備中獲取敏感數據，並利用這些信息對其他相關係統發起攻擊。反病毒和計算機安全服務公司卡巴斯基表示，在 2021，物聯網黑客數量同比增長了四倍多。</p><p>在很大程度上，黑客通過使用 Telnet 協議訪問物聯網網絡，該協議為通過互聯網與設備或服務器進行通信提供了命令列接口。根據研究報告，超過 58% 的物聯網入侵使用各種協議以求實現挖掘加密貨幣、通過分佈式拒絕服務（DDoS）攻擊關閉系統、竊取機密數據的目的。</p><p>由於人們在疫情期間居家使用物聯網設備的時間增加，安全風險也隨之上升。這些物聯網組件中的大部分無論是個人用還是商用，都缺乏基本的安全措施。人工智能和邊緣計算等新技術也使網絡和數據安全形勢複雜化。卡巴斯基的一位安全專家 Dan Demeter 表示：智能組件變得流行，攻擊的數量也隨之上升了。</p><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/03/Figure-1-Key-components-in-PENIOT.jpg" alt="Key components in PENIOT"></p><h3 id="物聯網組件的安全審計需求" tabindex="-1">物聯網組件的安全審計需求 <a class="header-anchor" href="#物聯網組件的安全審計需求" aria-label="Permalink to “物聯網組件的安全審計需求”">​</a></h3><p>網絡攻擊一直在演變，商業公司和政府部門都在採用越來越複雜的網絡安全設施以防止他們的應用和基礎設施免於在線攻擊。全球滲透測試市場預計將從 2021 的 16 億美元增長到 2026 年的 30 億美元，2021 至 2026 年的複合年增長率為 13.8%。</p><p>物聯網設備的滲透測試是一個熱門話題，在這一領域有大量研究。即使採用“設計安全”的方法，滲透對於識別真正的安全危險並採取適當的預防措施也是至關重要的。</p><p>物聯網部署中需要安全和隱私的關鍵部分和協議包括：</p><ul><li><ruby>受限應用協議<rt>Constraint application protocol</rt></ruby>（CoAP）</li><li><ruby>低功耗藍牙<rt>Bluetooth low energy</rt></ruby>（BLE）</li><li><ruby>高級消息隊列協議<rt>Advanced message queuing protocol</rt></ruby>（AMQP）</li><li><ruby>消息隊列遙測傳輸<rt>Message queuing telemetry transport</rt></ruby>（MQTT）</li></ul><p>攻擊者有多種可能的入口訪問到聯網設備。在物聯網滲透測試（或安全審計）時，要測試完整的物聯網場景和生態。測試內容包括從單個層和嵌入式軟件到通信協議和服務器的所有內容。對服務器、在線接口和移動應用的測試並非物聯網獨有，但至關重要，因為它們涵蓋了故障可能性很高的領域。物聯網漏洞是電氣、嵌入式軟件和通信協議測試的重點。</p><p>在評估聯網設備的安全性時會進行以下測試。這些測試都是使用不同的針對漏洞的高性能滲透測試和安全審計工具進行的：</p><ul><li>通信端口中的攻擊和操縱的測試</li><li>基於無線電信號捕獲和分析的 IoT 嗅探</li><li>接口和後門測試</li><li>緩衝區溢出測試</li><li>密碼破解測試</li><li>調試</li><li>密碼學分析</li><li>固件操縱測試</li><li>逆向工程</li><li>內存轉儲</li></ul><p><img src="https://www.opensourceforu.com/wp-content/uploads/2022/03/Screenshot-2022-05-02-153653-590x282.png" alt=""></p><h3 id="物聯網安全審計使用的開源工具" tabindex="-1">物聯網安全審計使用的開源工具 <a class="header-anchor" href="#物聯網安全審計使用的開源工具" aria-label="Permalink to “物聯網安全審計使用的開源工具”">​</a></h3><p>物聯網設備在我們的日常生活中變得越來越普遍，比如，智能自行車、健身跟蹤器、醫療傳感器、智能鎖和聯動工廠等。所有這些設備和組件都可以使用開源工具來抵禦網絡攻擊，本文將簡要介紹其中一些工具。</p><h4 id="peniot" tabindex="-1">PENIOT <a class="header-anchor" href="#peniot" aria-label="Permalink to “PENIOT”">​</a></h4>',19)),r("p",null,[o(e,{href:"https://github.com/yakuza8/peniot"},{default:i(()=>[...t[0]||(t[0]=[l("PENIOT",-1)])]),_:1}),t[1]||(t[1]=l(" 是一種物聯網滲透測試工具，使安全審計團隊能夠通過利用設備的連接來測試和破壞具有各種安全威脅的設備。可以測試主動和被動安全威脅。在確定目標設備和相關信息（或參數）後，可以進行主動安全攻擊，例如改變系統資源、重放合法通信單元等。還可以分析被動安全威脅，例如破壞敏感數據的機密性或訪問網絡流量分析。",-1))]),t[30]||(t[30]=r("h4",{id:"objection",tabindex:"-1"},[l("Objection "),r("a",{class:"header-anchor",href:"#objection","aria-label":"Permalink to “Objection”"},"​")],-1)),r("p",null,[o(e,{href:"https://github.com/sensepost/objection"},{default:i(()=>[...t[2]||(t[2]=[l("Objective",-1)])]),_:1}),t[3]||(t[3]=l(" 是一個對物聯網環境中使用的安卓和 iOS 應用程序進行詳細分析和安全審計的工具。",-1))]),t[31]||(t[31]=r("p",null,"目前許多智能組件和設備都在使用安卓和 iOS 平台，使用該工具可以通過詳細的日誌和安全審計報告對這些平台進行分析。",-1)),t[32]||(t[32]=r("h4",{id:"routersploit",tabindex:"-1"},[l("Routersploit "),r("a",{class:"header-anchor",href:"#routersploit","aria-label":"Permalink to “Routersploit”"},"​")],-1)),r("p",null,[o(e,{href:"https://github.com/threat9/routersploit"},{default:i(()=>[...t[4]||(t[4]=[l("這個",-1)])]),_:1}),t[5]||(t[5]=l(" 針對嵌入式設備的開源開發框架具有多個用於滲透測試和安全審計的功能和模組：",-1))]),t[33]||(t[33]=r("ul",null,[r("li",null,"Exploits —— 漏洞評估"),r("li",null,"Creds —— 網絡服務和證書的測試"),r("li",null,"Scanners —— 對目標進行詳細的安全審計"),r("li",null,"Payloads —— 有效載荷和注入關鍵點的生成"),r("li",null,"Generic —— 執行和測試攻擊")],-1)),t[34]||(t[34]=r("h4",{id:"wireshark",tabindex:"-1"},[l("Wireshark "),r("a",{class:"header-anchor",href:"#wireshark","aria-label":"Permalink to “Wireshark”"},"​")],-1)),r("p",null,[o(e,{href:"https://www.wireshark.org"},{default:i(()=>[...t[6]||(t[6]=[l("Wireshark",-1)])]),_:1}),t[7]||(t[7]=l(" 是一款功能豐富的、免費的網絡協議分析器。MQTT 等多種物聯網協議可通過該工具實現有效分析。為了發現弱點，可以根據協議配置安全規則並檢查流量。可以使用 ",-1)),t[8]||(t[8]=r("code",null,"tcpdump",-1)),t[9]||(t[9]=l(" 通過命令列訪問網絡數據包分析器。此類工具用於檢查物聯網設備和網絡之間交換的數據包。",-1))]),t[35]||(t[35]=r("h4",{id:"binwalk",tabindex:"-1"},[l("Binwalk "),r("a",{class:"header-anchor",href:"#binwalk","aria-label":"Permalink to “Binwalk”"},"​")],-1)),r("p",null,[o(e,{href:"https://www.kali.org/tools/binwalk"},{default:i(()=>[...t[10]||(t[10]=[l("Binwalk",-1)])]),_:1}),t[11]||(t[11]=l(" 是一種逆向硬件設計的工具。它是 Kali Linux 的關鍵組件之一，用於滲透測試、服務器指紋識別、安全審計和取證應用。",-1))]),t[36]||(t[36]=r("h4",{id:"firmwalker",tabindex:"-1"},[l("Firmwalker "),r("a",{class:"header-anchor",href:"#firmwalker","aria-label":"Permalink to “Firmwalker”"},"​")],-1)),r("p",null,[o(e,{href:"https://github.com/craigz28/firmwalker"},{default:i(()=>[...t[12]||(t[12]=[l("Firmwalker",-1)])]),_:1}),t[13]||(t[13]=l(" 是一款自由開源的工具，用於搜索和掃描固件文件系統，無論是否被提取或掛載。使用這個工具可以做一個詳細的安全審計。",-1))]),t[37]||(t[37]=r("p",null,"在物聯網（IoT）和萬物互聯（IoE）的時代，有必要設計並使用高性能工具包進行滲透測試和安全審計。隨着物聯網設備數量的增加，安全風險也在增加。為了物聯網和萬物互聯部署有更高級別的安全和隱私，有必要根據最新的協議和動態的流量定製化自由及開源的工具箱和軟件包。",-1)),t[38]||(t[38]=r("hr",null,null,-1)),r("p",null,[t[15]||(t[15]=l("via: ",-1)),o(e,{href:"https://www.opensourceforu.com/2022/05/tools-you-can-use-for-the-security-audit-of-iot-devices/"},{default:i(()=>[...t[14]||(t[14]=[l("https://www.opensourceforu.com/2022/05/tools-you-can-use-for-the-security-audit-of-iot-devices/",-1)])]),_:1})]),r("p",null,[t[20]||(t[20]=l("作者：",-1)),o(e,{href:"https://www.opensourceforu.com/author/dr-gaurav-kumar/"},{default:i(()=>[...t[16]||(t[16]=[l("Dr Kumar Gaurav",-1)])]),_:1}),t[21]||(t[21]=l(" 選題：",-1)),o(e,{href:"https://github.com/lkxed"},{default:i(()=>[...t[17]||(t[17]=[l("lkxed",-1)])]),_:1}),t[22]||(t[22]=l(" 譯者：",-1)),o(e,{href:"https://github.com/tendertime"},{default:i(()=>[...t[18]||(t[18]=[l("tendertime",-1)])]),_:1}),t[23]||(t[23]=l(" 校對：",-1)),o(e,{href:"https://github.com/wxy"},{default:i(()=>[...t[19]||(t[19]=[l("wxy",-1)])]),_:1})]),r("p",null,[t[26]||(t[26]=l("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[24]||(t[24]=[l("LCTT",-1)])]),_:1}),t[27]||(t[27]=l(" 原創編譯，",-1)),o(e,{href:"https://linux.cn/"},{default:i(()=>[...t[25]||(t[25]=[l("Linux中國",-1)])]),_:1}),t[28]||(t[28]=l(" 榮譽推出",-1))])])}const y=n(d,[["render",f]]);export{h as __pageData,y as default};
